def _pruefe_zaehlungen():
    """Jede im Text genannte Zahl gegen die MACULA-Lemmata prüfen."""
    cache = {}
    fehler = []
    for buch, lemma, von, bis, soll in ZAEHLUNGEN:
        if buch not in cache:
            ent = {}
            for f in sorted((D / "annotations").glob(f"MACULA-SBLGNT-{buch}-0*.json")):
                ent.update(json.loads(f.read_text(encoding="utf-8"))["entries"])
            cache[buch] = ent
        ist = 0
        for tid, e in cache[buch].items():
            if e.get("lemma") != lemma:
                continue
            c, v = (int(x) for x in tid.split("-")[3:5])
            if von <= (c, v) <= bis:
                ist += 1
        if ist != soll:
            fehler.append(f"{buch} {lemma} {von}–{bis}: erwartet {soll}, gefunden {ist}")
    if fehler:
        raise SystemExit("Zählungen stimmen nicht:\n" + "\n".join(fehler))


def _pruefe_fachwoerter():
    """Griechische und hebräische Wörter in Deutungen und Hintergrund müssen als terms erfasst sein."""
    wort = re.compile(r"[Ͱ-Ͽἀ-῿][Ͱ-Ͽἀ-῿̀-ͯ]*|[֐-׿]+")
    fehlend = []
    for rec in INTERPRETATIONS:
        texte = [rec[3], rec[5]] + rec[6]
        erfasst = " ".join(t[1] for t in rec[7])
        fehlend += [(rec[0], w) for t in texte for w in wort.findall(t) if w not in erfasst]
    for rec in BACKGROUND:
        texte = [rec[6], rec[7] or ""]
        erfasst = " ".join(t[1] for t in rec[10])
        fehlend += [(rec[0], w) for t in texte for w in wort.findall(t) if w not in erfasst]
    if fehlend:
        raise SystemExit("Ursprachwörter ohne terms: " + "; ".join(f"{i}: {w}" for i, w in fehlend))


def run():
    import _study
    _pruefe_zaehlungen()
    _pruefe_fachwoerter()
    _study.DATE = "2026-10-14"
    _study.AUTH = "KI-Entwurf (Claude) vom 2026-10-14 auf Wunsch von Andi Neck; keine fachliche Prüfung erfolgt."
    _study.AUTH_GSW = ("KI-Entwurf (Claude) vom 2026-10-14; aus dem Hochdeutschen in Züridüütsch gefasst; "
                       "Mundart noch nicht muttersprachlich geprüft.")
    # Bestehenden Kontext unverändert weitergeben: _lib.write erkennt Gleichheit und schreibt nichts.
    context = json.loads((D / "contexts" / f"{CTX_READERS}.json").read_text(encoding="utf-8"))
    extra = sorted((p.stem for ch in range(15, 22) for p in (D / "translations").glob(f"TRANS-JHN-{ch:03d}-*-WORKING.json")),
                   key=lambda x: ("-GSW-" in x, x))
    extra += [s[0] for s in SUMMARIES]
    _study.write_study({"TAGS": TAGS, "CONTEXT": context, "FINDINGS": FINDINGS, "INTERPRETATIONS": INTERPRETATIONS,
                        "PRINCIPLES": PRINCIPLES, "APPLICATIONS": APPLICATIONS, "QUESTIONS": QUESTIONS, "RELATIONS": RELATIONS,
                        "BACKGROUND": BACKGROUND, "SUMMARIES": SUMMARIES,
                        "STUDY": ("STUDY-JHN-0003", "Johannes 15–21: Abschiedsreden, Gebet, Passion und Erscheinungen", CHAPTERS[15], extra,
                                  ["Mundart muttersprachlich prüfen", "Fachliche Prüfung der Deutungen und des Hintergrunds",
                                   "Handschriftenangaben (FIND-JHN-3008, FIND-JHN-3013, FIND-JHN-3020, FIND-JHN-3021) am Faksimile bzw. an einem kritischen Apparat prüfen",
                                   "Literaturangaben (Käsemann 1966, Meeks 1972, Bultmann 1941, Bond 1998, Lowe 1976, Mason 2007, Reinhartz 2018, Meier 1991, Jeremias 1935, Jaubert 1957, Trench, Westcott 1881, Brown 1979, Emerton 1958, Haas 1970, Zias/Sekeles 1985, Humphreys/Waddington 1983) und antike Stellenangaben bibliographisch prüfen",
                                   "Kapitelzusammenfassungen nach Abschluss des Gegenlesens der Übersetzungen erneut gegen den Text prüfen"])},
                       "Johannes 15–21")


if __name__ == "__main__":
    run()
